import pandas as pd


def _differs(a, b):
    a_null = pd.isna(a)
    b_null = pd.isna(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_store = inputs["dim_store"].copy()
    stg = inputs["stg_store_full"].copy()
    batch = inputs["batch_control"].copy()

    b = batch["batch_date"].iloc[0]

    # S := SELECT DISTINCT store_id, region, format FROM STG_STORE_FULL
    S = stg.drop_duplicates(subset=["store_id", "region", "format"]).copy()
    S_store_ids = set(S["store_id"].tolist())

    # Build map of current rows: store_id -> (original_index, region, format)
    current_mask = dim_store["is_current"] == 1
    current_df = dim_store[current_mask]

    current_map = {}
    for idx, row in current_df.iterrows():
        current_map[row["store_id"]] = (idx, row["region"], row["format"])

    closed_indices = set()
    new_rows = []

    # Step 1: process each store in the snapshot
    for _, s in S.iterrows():
        store_id = s["store_id"]
        region = s["region"]
        fmt = s["format"]

        if store_id in current_map:
            orig_idx, c_region, c_format = current_map[store_id]
            if _differs(c_region, region) or _differs(c_format, fmt):
                closed_indices.add(orig_idx)
                new_rows.append({
                    "store_id": store_id,
                    "region": region,
                    "format": fmt,
                    "eff_start_date": b,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: no-op
        else:
            # brand-new store OR reactivated store
            new_rows.append({
                "store_id": store_id,
                "region": region,
                "format": fmt,
                "eff_start_date": b,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })

    # Step 2: close current rows whose store_id is not in S
    for store_id, (orig_idx, _, _) in current_map.items():
        if store_id not in S_store_ids:
            closed_indices.add(orig_idx)

    dim_store_out = dim_store.copy()

    for idx in closed_indices:
        dim_store_out.at[idx, "eff_end_date"] = b
        dim_store_out.at[idx, "is_current"] = 0

    if new_rows:
        new_df = pd.DataFrame(
            new_rows,
            columns=["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"],
        )
        dim_store_out = pd.concat([dim_store_out, new_df], ignore_index=True)
    else:
        dim_store_out = dim_store_out.reset_index(drop=True)

    dim_store_out = dim_store_out[
        ["store_id", "region", "format", "eff_start_date", "eff_end_date", "is_current"]
    ]

    return {"dim_store_out": dim_store_out}
